import type { Product } from '../types/product'

const base = import.meta.env.BASE_URL

/** Asset paths are generated by `scripts/prepare-assets.mjs` from the source folders in the project root. */
const asset = (id: string, file: string) => `${base}products/${id}/${file}`

/**
 * Centralized product catalogue.
 *
 * Source assets:
 *  - chair   ← Chair/chair GLB.glb             + "Modern Grey Fabric Armchair with Wooden Frame.png"
 *  - sofa    ← Sofa/modern_sofa.glb            + "Elegant Ivory Loveseat with Wooden Legs.png"
 *  - tea-pot ← Tea_pot/cloisonne_tea_pot.glb   + "Ornate Golden Floral Ceramic Teapot.png"
 *  - cycle   ← Cycle/bmx_cycle.glb (meshopt)   + "Glossy Red and Yellow BMX Bicycle.png"
 *  - art     ← Art/abstract_geometric_canvas_paintings_low_poly.glb + "Abstract Geometric Mosaic Canvas Print.png"
 *
 * Dimensions are nominal real-world sizes in meters. Each model is normalized from its
 * bounding box so the `fitAxis` dimension matches, preserving the model's proportions.
 */
export const PRODUCTS: Product[] = [
  {
    id: 'chair',
    name: 'Chair',
    category: 'Living Room',
    description: 'Modern grey fabric armchair with a warm solid-wood frame.',
    thumbnail: asset('chair', 'thumbnail.webp'),
    modelPath: asset('chair', 'model.glb'),
    dimensions: { width: 0.78, height: 0.85, depth: 0.99 },
    fitAxis: 'height',
    defaultScale: 1,
    placement: 'floor',
    rotation: { step: 45, initialYaw: 0 },
    scale: { allowScale: true, min: 0.5, max: 2 },
    accent: '#7dd3fc',
  },
  {
    id: 'sofa',
    name: 'Sofa',
    category: 'Living Room',
    description: 'Elegant ivory loveseat with rolled arms and tapered wooden legs.',
    thumbnail: asset('sofa', 'thumbnail.webp'),
    modelPath: asset('sofa', 'model.glb'),
    dimensions: { width: 1.9, height: 0.91, depth: 0.79 },
    fitAxis: 'height',
    defaultScale: 1,
    placement: 'floor',
    rotation: { step: 45, initialYaw: 0 },
    scale: { allowScale: true, min: 0.5, max: 2 },
    accent: '#e9d8b4',
  },
  {
    id: 'tea-pot',
    name: 'Tea Pot',
    category: 'Tableware',
    description: 'Ornate cloisonné ceramic teapot with hand-painted golden florals.',
    thumbnail: asset('tea-pot', 'thumbnail.webp'),
    modelPath: asset('tea-pot', 'model.glb'),
    // Fitted by width (spout to handle) — a compact serving teapot rather than a display piece.
    dimensions: { width: 0.26, height: 0.14, depth: 0.16 },
    fitAxis: 'width',
    defaultScale: 1,
    placement: 'tabletop',
    rotation: { step: 30, initialYaw: 0 },
    scale: { allowScale: true, min: 0.5, max: 2 },
    accent: '#fbbf24',
  },
  {
    id: 'cycle',
    name: 'Cycle',
    category: 'Outdoor',
    description: 'Glossy red and yellow 20" BMX bike built for street and park.',
    thumbnail: asset('cycle', 'thumbnail.webp'),
    modelPath: asset('cycle', 'model.glb'),
    dimensions: { width: 0.6, height: 1.0, depth: 1.65 },
    fitAxis: 'longest',
    defaultScale: 1,
    placement: 'floor',
    rotation: { step: 45, initialYaw: 0 },
    scale: { allowScale: true, min: 0.5, max: 2 },
    accent: '#f87171',
  },
  {
    id: 'art',
    name: 'Wall Art',
    category: 'Decor',
    description: 'Pair of abstract geometric mosaic canvases in vivid, hand-drawn color.',
    thumbnail: asset('art', 'thumbnail.webp'),
    modelPath: asset('art', 'model.glb'),
    dimensions: { width: 1.52, height: 0.8, depth: 0.02 },
    fitAxis: 'height',
    // The source canvases face +X; turn them so the painted side faces out from the wall (+Z).
    modelYaw: -90,
    defaultScale: 1,
    placement: 'wall',
    rotation: { step: 0, initialYaw: 0 },
    scale: { allowScale: true, min: 0.5, max: 2 },
    accent: '#a78bfa',
  },
]

export const getProduct = (id: string) => PRODUCTS.find((p) => p.id === id)

export const formatDimensions = ({ width, height, depth }: Product['dimensions']) => {
  const cm = (m: number) => Math.round(m * 100)
  return `${cm(width)} × ${cm(height)} × ${cm(depth)} cm`
}
